#!/usr/bin/env python3
"""Genera interfaces I20 offline separadas, sin geografía, proveedor ni predicciones."""
from __future__ import annotations
import argparse,hashlib,json,shutil
from pathlib import Path
import sys
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from src.tfg_phase0.i20_annotation_workflow import annotation_active_ids,build_annotation_fixture,build_scene_fixture,validate_scene_review
from src.tfg_phase0.i20_preparation import canonical_bytes
def load(path):return json.loads(path.read_text(encoding='utf-8'))
def write(path,value):path.write_bytes(canonical_bytes(value)+b'\n')
def checksums(root):
 rows=[]
 for path in sorted(root.rglob('*')):
  if path.is_file() and path.name!='CHECKSUMS.sha256':rows.append(f"{hashlib.sha256(path.read_bytes()).hexdigest()}  {path.relative_to(root).as_posix()}")
 (root/'CHECKSUMS.sha256').write_text('\n'.join(rows)+'\n',encoding='utf-8')
BASE_CSS="""*{box-sizing:border-box}body{font:15px system-ui;margin:0;background:#eef0ec;color:#18201c}header{position:sticky;top:0;background:#19352c;color:white;padding:12px;z-index:2}main{max-width:1180px;margin:auto;padding:18px}.card{background:white;border:1px solid #ccd4ce;border-radius:10px;padding:16px;margin:14px 0}img{max-width:100%;max-height:520px;object-fit:contain;background:#ddd}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}textarea,input,select,button{font:inherit;padding:8px;width:100%;margin:4px 0 10px}button{cursor:pointer}.claim{border-left:4px solid #557b68;padding:8px;margin:8px 0;background:#f4f6f3}.warn{background:#fff3cd;padding:10px}.status{font-weight:700}.init-error{display:none;background:#f8d7da;color:#721c24;border:1px solid #f1aeb5;padding:12px;margin:12px 0;white-space:pre-wrap}@media(max-width:750px){.grid{grid-template-columns:1fr}}"""
COMMON_JS="""const stable=v=>{if(Array.isArray(v))return '['+v.map(stable).join(',')+']';if(v&&typeof v==='object')return '{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+stable(v[k])).join(',')+'}';return JSON.stringify(v)};const sha=async s=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)))].map(x=>x.toString(16).padStart(2,'0')).join('');const save=(name,obj)=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)+'\\n'],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};const readFile=input=>new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>{try{ok(JSON.parse(r.result))}catch(e){no(e)}};r.onerror=no;r.readAsText(input.files[0])});"""
ERROR_BOOTSTRAP="""<script>window.__showInitError=function(message){const box=document.getElementById('init-error');if(box){box.style.display='block';box.textContent='Error al inicializar la interfaz: '+message}};window.addEventListener('error',event=>window.__showInitError(event.message||'error JavaScript desconocido'));window.addEventListener('unhandledrejection',event=>window.__showInitError(event.reason?.message||String(event.reason||'promesa rechazada')));</script>"""
def harden_html(html):
 html=html.replace('<div id="cards"></div>','<div id="init-error" class="init-error" role="alert"></div><div id="cards"></div>')
 html=html.replace('<script type="application/json" id="fixture">',ERROR_BOOTSTRAP+'<script type="application/json" id="fixture">')
 replacements={
  'export.onclick':"document.getElementById('export').onclick",'export.disabled':"document.getElementById('export').disabled",
  'load.onchange':"document.getElementById('load').onchange",'load.onclick':"document.getElementById('load').onclick",
  'draft.onchange':"document.getElementById('draft').onchange",'cards.innerHTML':"document.getElementById('cards').innerHTML",
  'fixture.textContent':"document.getElementById('fixture').textContent",'who.value':"document.getElementById('who').value",
  'readFile(load)':"readFile(document.getElementById('load'))",'readFile(draft)':"readFile(document.getElementById('draft'))",
  'readFile(ann)':"readFile(document.getElementById('ann'))",'readFile(ra)':"readFile(document.getElementById('ra'))",'readFile(rb)':"readFile(document.getElementById('rb'))",
 }
 for old,new in replacements.items():html=html.replace(old,new)
 return html
def annotation_html(fixture):
 data=json.dumps(fixture,ensure_ascii=False).replace('</','<\\/')
 return f'''<!doctype html><html lang="es"><meta charset="utf-8"><title>I20 Anotación</title><style>{BASE_CSS}</style><header><b>I01–I20 · anotación ciega</b><div>Solo la imagen. Sin mapas, GT, OSM ni predicciones.</div></header><main><div class="warn">No invente nombres ilegibles. Las relaciones izquierda/derecha pertenecen al encuadre salvo evidencia independiente.</div><label>Descriptor pseudónimo<input id="who"></label><label>Cargar borrador JSON<input id="load" type="file" accept="application/json"></label><button id="export">Exportar JSON presentado</button><div id="cards"></div></main><script type="application/json" id="fixture">{data}</script><script>{COMMON_JS}
const f=JSON.parse(document.querySelector('#fixture').textContent), state={{}};const kinds=['object_presence','attribute','visible_text','scene_structure','camera_frame_relation','egocentric_relation','other_observable'];
function render(){{cards.innerHTML=f.observations.map(o=>`<section class="card" data-id="${{o.observation_id}}"><h2>${{o.observation_id}}</h2><img src="${{o.reference_asset_path}}" alt="Referencia ${{o.observation_id}}"><label>Descripción española<textarea class="desc" rows="6"></textarea></label><label>Incertidumbre<select class="unc"><option>adequate</option><option>limited</option><option>insufficient</option></select></label><label>Limitaciones (separadas por coma)<input class="limits"></label><label>Orientación<select class="orient"><option value="unknown">desconocida</option><option value="camera_heading_reported">heading de cámara reportado</option></select></label><h3>Claims observables</h3><div class="claims"></div><button type="button" class="add">Añadir claim</button></section>`).join('');document.querySelectorAll('.add').forEach(b=>b.onclick=()=>addClaim(b.closest('.card').querySelector('.claims')))}}
function addClaim(root,v={{}}){{const d=document.createElement('div');d.className='claim';d.innerHTML=`<label>Texto literal del claim<input class="ct" value="${{v.text_es||''}}"></label><label>Inicio<input class="cs" type="number" min="0" value="${{v.start??0}}"></label><label>Fin<input class="ce" type="number" min="1" value="${{v.end??1}}"></label><label>Tipo<select class="ck">${{kinds.map(k=>`<option ${{v.kind===k?'selected':''}}>${{k}}</option>`).join('')}}</select></label><label>Observabilidad<select class="co"><option>direct</option><option>partially_observable</option><option>uncertain</option></select></label><label>Certeza<select class="cc"><option>certain</option><option>probable</option><option>uncertain</option></select></label><label><input class="ocr" type="checkbox" style="width:auto"> Requiere OCR</label><label><input class="ori" type="checkbox" style="width:auto"> Requiere orientación</label><button class="del" type="button">Eliminar</button><small class="preview"></small>`;d.querySelector('.del').onclick=()=>d.remove();const update=()=>{{const card=d.closest('.card'),text=card.querySelector('.desc').value,s=+d.querySelector('.cs').value,e=+d.querySelector('.ce').value;d.querySelector('.preview').textContent='Span: '+text.slice(s,e)}};d.querySelectorAll('input').forEach(x=>x.oninput=update);root.append(d);update()}}
async function build(){{if(!who.value.trim())throw Error('Falta descriptor');const observations=[];for(const o of f.observations){{const card=document.querySelector(`[data-id="${{o.observation_id}}"]`),description=card.querySelector('.desc').value.trim();if(!description)throw Error('Falta descripción '+o.observation_id);const claims=[];for(const node of card.querySelectorAll('.claim')){{const text=node.querySelector('.ct').value,s=+node.querySelector('.cs').value,e=+node.querySelector('.ce').value;if(description.slice(s,e)!==text)throw Error('Span no literal '+o.observation_id);const kind=node.querySelector('.ck').value,requiresOrientation=node.querySelector('.ori').checked,payload={{kind,text_es:text,span:{{start:s,end:e}},observability:node.querySelector('.co').value,certainty:node.querySelector('.cc').value,requires_ocr:node.querySelector('.ocr').checked,requires_orientation:requiresOrientation,orientation_frame:requiresOrientation?'camera_frame':'unknown',limitations:[]}};claims.push({{claim_id:'i20-claim-sha256-'+await sha(stable(payload)),...payload}})}}if(!claims.length)throw Error('Falta claim '+o.observation_id);const orientation=card.querySelector('.orient').value==='unknown'?{{status:'unknown',bearing_degrees:null,uncertainty_degrees:null,meaning:'unknown',source:'not_available',evidence_ids:[],cardinal_conversion_allowed:false}}:{{status:'camera_heading_reported',bearing_degrees:null,uncertainty_degrees:null,meaning:'camera_heading',source:'provider_metadata',evidence_ids:[],cardinal_conversion_allowed:false}};observations.push({{observation_id:o.observation_id,reference_asset_id:o.reference_asset_id,reference_asset_sha256:o.reference_asset_sha256,reference_asset_path:o.reference_asset_path,descriptor_pseudonym:who.value.trim(),described_at_utc:new Date().toISOString(),description_es:description,description_sha256:await sha(description),description_status:'submitted',uses_external_context:false,mentions_inferred_location:false,claims,visual_uncertainty:{{overall_status:card.querySelector('.unc').value,limitations:card.querySelector('.limits').value.split(',').map(x=>x.trim()).filter(Boolean),notes_es:null}},orientation}})}}const doc={{schema_version:'1.0',contract_version:'i20-annotation-package-v1',package_id:'',status:'annotation_open',expected_observation_ids:f.expected_observation_ids,reference_policy:'single_designated_reference_visual_only',language_policy:'original_spanish',blinding:{{rankings_present:false,predictions_present:false,ground_truth_present:false,candidate_information_present:false}},source_ledger:null,instructions_sha256:f.instructions_sha256,observations}};doc.package_id='i20-annotation-package-sha256-'+await sha(stable(Object.fromEntries(Object.entries(doc).filter(([k])=>k!=='package_id'))));return doc}}
export.onclick=async()=>{{try{{save('i20-annotation-submitted.json',await build())}}catch(e){{alert(e.message)}}}};load.onchange=async()=>{{try{{const d=await readFile(load);if(d.contract_version!=='i20-annotation-package-v1')throw Error('Contrato incompatible');who.value=d.observations[0]?.descriptor_pseudonym||'';for(const row of d.observations){{const c=document.querySelector(`[data-id="${{row.observation_id}}"]`);c.querySelector('.desc').value=row.description_es;c.querySelector('.claims').innerHTML='';row.claims.forEach(x=>addClaim(c.querySelector('.claims'),{{...x,start:x.span.start,end:x.span.end}}))}}}}catch(e){{alert(e.message)}}}};render();document.documentElement.dataset.ready='true';</script></html>'''
def scene_html(fixture):
 data=json.dumps(fixture,ensure_ascii=False).replace('</','<\\/')
 return f'''<!doctype html><html lang="es"><meta charset="utf-8"><title>I20 Escenas</title><style>{BASE_CSS}</style><header><b>I01–I20 · revisión de escenas</b><div>Sin coordenadas, distancias ni holdout.</div></header><main><label>Revisor humano<input id="who"></label><label>Cargar borrador<input id="draft" type="file" accept="application/json"></label><button id="export">Exportar revisión</button><div id="cards"></div></main><script type="application/json" id="fixture">{data}</script><script>{COMMON_JS}const f=JSON.parse(fixture.textContent);const opts='<option value="">pendiente</option><option>yes</option><option>no</option><option>uncertain</option>';cards.innerHTML=f.records.map(r=>`<section class="card" data-pair="${{r.pair_id}}"><h2>${{r.left_observation_id}} / ${{r.right_observation_id}}</h2><div class="grid"><img src="${{r.left_reference_path}}"><img src="${{r.right_reference_path}}"></div>${{[['same_scene','Misma escena'],['distinctive_objects_shared','Objetos distintivos compartidos'],['field_of_view_overlap','Solapamiento FOV'],['same_place_different_frame','Mismo lugar, otro encuadre']].map(([k,l])=>`<label>${{l}}<select data-k="${{k}}">${{opts}}</select></label>`).join('')}}<label>Decisión<select class="decision"><option value="">pendiente</option><option>CLEAR</option><option>EXCLUDE</option><option>REVIEW</option></select></label><label>Notas<textarea class="notes"></textarea></label></section>`).join('');draft.onchange=async()=>{{try{{const d=await readFile(draft);if(d.contract_version!=='i20-scene-review-v1'||d.fixture_sha256!==f.fixture_sha256||d.records.length!==f.records.length)throw Error('Borrador incompatible');who.value=d.reviewer_pseudonym||'';for(const r of d.records){{const c=document.querySelector(`[data-pair="${{r.pair_id}}"]`);if(!c)throw Error('Par desconocido');for(const k of ['same_scene','distinctive_objects_shared','field_of_view_overlap','same_place_different_frame'])c.querySelector(`[data-k="${{k}}"]`).value=r[k];c.querySelector('.decision').value=r.decision;c.querySelector('.notes').value=r.notes_es||''}}}}catch(e){{alert(e.message)}}}};export.onclick=async()=>{{try{{if(!who.value.trim())throw Error('Falta revisor');const records=f.records.map(r=>{{const c=document.querySelector(`[data-pair="${{r.pair_id}}"]`),get=k=>c.querySelector(`[data-k="${{k}}"]`).value,decision=c.querySelector('.decision').value;if(!decision||['same_scene','distinctive_objects_shared','field_of_view_overlap','same_place_different_frame'].some(k=>!get(k)))throw Error('Fila incompleta');return{{pair_id:r.pair_id,left_observation_id:r.left_observation_id,right_observation_id:r.right_observation_id,same_scene:get('same_scene'),distinctive_objects_shared:get('distinctive_objects_shared'),field_of_view_overlap:get('field_of_view_overlap'),same_place_different_frame:get('same_place_different_frame'),decision,notes_es:c.querySelector('.notes').value}}}});const doc={{schema_version:'1.0',contract_version:'i20-scene-review-v1',package_id:'',fixture_sha256:f.fixture_sha256,status:'submitted',reviewer_pseudonym:who.value.trim(),reviewed_at_utc:new Date().toISOString(),records}};doc.package_id='i20-scene-review-sha256-'+await sha(stable(Object.fromEntries(Object.entries(doc).filter(([k])=>k!=='package_id'))));save('i20-scene-review-submitted.json',doc)}}catch(e){{alert(e.message)}}}};document.documentElement.dataset.ready='true';</script></html>'''
def review_html(role,fixture):
 data=json.dumps(fixture,ensure_ascii=False).replace('</','<\\/')
 return f'''<!doctype html><html lang="es"><meta charset="utf-8"><title>I20 Revisión {role}</title><style>{BASE_CSS}</style><header><b>I01–I20 · Revisor {role}</b><div>No cargue ni consulte la revisión del otro revisor.</div></header><main><label>Pseudónimo<input id="who"></label><label>Cargar anotación presentada<input id="load" type="file" accept="application/json"></label><button id="export" disabled>Exportar revisión {role}</button><div id="cards"></div></main><script type="application/json" id="fixture">{data}</script><script>{COMMON_JS}const f=JSON.parse(fixture.textContent);let ann=null;load.onchange=async()=>{{try{{ann=await readFile(load);if(ann.contract_version!=='i20-annotation-package-v1'||ann.observations.length!==20)throw Error('Anotación incompatible');cards.innerHTML=ann.observations.map(o=>{{const ref=f.observations.find(x=>x.observation_id===o.observation_id);return`<section class="card" data-id="${{o.observation_id}}"><h2>${{o.observation_id}}</h2><img src="${{ref.reference_asset_path}}"><p>${{o.description_es.replaceAll('&','&amp;').replaceAll('<','&lt;')}}</p><label>Decisión<select class="decision"><option>accept</option><option>revise</option><option>exclude</option></select></label><label>Fidelidad<select class="faith"><option>pass</option><option>fail</option></select></label><label>Solo observable<select class="observable"><option>pass</option><option>fail</option></select></label><label>Orientación<select class="orientation"><option>pass</option><option>fail</option><option>not_applicable</option></select></label><label>Incertidumbre<select class="uncertainty"><option>pass</option><option>fail</option></select></label><div>${{o.claims.map(c=>`<div class="claim" data-claim="${{c.claim_id}}"><b>${{c.text_es}}</b><select class="verdict"><option>supported</option><option>unsupported</option><option>unverifiable</option></select><select class="atomic"><option>pass</option><option>fail</option></select><label><input class="span" type="checkbox" checked style="width:auto"> span válido</label><label><input class="frame" type="checkbox" checked style="width:auto"> frame válido</label></div>`).join('')}}</div></section>`}}).join('');export.disabled=false}}catch(e){{alert(e.message)}}}};export.onclick=async()=>{{try{{if(!ann||!who.value.trim())throw Error('Faltan inputs');const reviews=ann.observations.map(o=>{{const c=document.querySelector(`[data-id="${{o.observation_id}}"]`);return{{observation_id:o.observation_id,reviewer_pseudonym:who.value.trim(),review_round:'independent',predictions_available:false,ground_truth_available:false,other_reviewer_output_available:false,decision:c.querySelector('.decision').value,description_faithfulness:c.querySelector('.faith').value,observable_only:c.querySelector('.observable').value,orientation_handling:c.querySelector('.orientation').value,uncertainty_handling:c.querySelector('.uncertainty').value,claim_reviews:[...c.querySelectorAll('.claim')].map(x=>({{claim_id:x.dataset.claim,verdict:x.querySelector('.verdict').value,atomicity:x.querySelector('.atomic').value,evidence_span_valid:x.querySelector('.span').checked,orientation_frame_valid:x.querySelector('.frame').checked}})),exclusion_reasons:[],reviewed_at_utc:new Date().toISOString()}}}});const doc={{schema_version:'1.0',contract_version:'i20-review-package-v1',package_id:'',status:'review_open',annotation_package_id:ann.package_id,reviewer_count:2,reviews,adjudication:[]}};doc.package_id='i20-review-package-sha256-'+await sha(stable(Object.fromEntries(Object.entries(doc).filter(([k])=>k!=='package_id'))));save('i20-review-{role.lower()}.json',doc)}}catch(e){{alert(e.message)}}}};document.documentElement.dataset.ready='true';</script></html>'''
def adjudication_html(fixture):
 data=json.dumps(fixture,ensure_ascii=False).replace('</','<\\/')
 return f'''<!doctype html><html lang="es"><meta charset="utf-8"><title>I20 Adjudicación</title><style>{BASE_CSS}</style><header><b>I01–I20 · adjudicación</b><div>Solo discrepancias. No se permiten hechos ni claims nuevos.</div></header><main><label>Adjudicador<input id="who"></label><label>Anotación<input id="ann" type="file" accept="application/json"></label><label>Revisión A<input id="ra" type="file" accept="application/json"></label><label>Revisión B<input id="rb" type="file" accept="application/json"></label><button id="load">Cargar discrepancias</button><button id="export" disabled>Exportar paquete combinado</button><div id="cards"></div></main><script type="application/json" id="fixture">{data}</script><script>{COMMON_JS}const f=JSON.parse(fixture.textContent);let A,B,N,diffs={{}};const key=r=>r.observation_id;function differences(a,b){{const d=[];['decision','description_faithfulness','observable_only','orientation_handling','uncertainty_handling'].forEach(k=>{{if(a[k]!==b[k])d.push(k)}});const ac=Object.fromEntries(a.claim_reviews.map(x=>[x.claim_id,x])),bc=Object.fromEntries(b.claim_reviews.map(x=>[x.claim_id,x]));for(const id of new Set([...Object.keys(ac),...Object.keys(bc)]))for(const k of ['verdict','atomicity','evidence_span_valid','orientation_frame_valid'])if(ac[id]?.[k]!==bc[id]?.[k])d.push(`claim:${{id}}:${{k}}`);if(a.decision!=='accept'||b.decision!=='accept')d.push('non_accept_decision');return[...new Set(d)]}}load.onclick=async()=>{{try{{[N,A,B]=await Promise.all([readFile(ann),readFile(ra),readFile(rb)]);if(A.annotation_package_id!==N.package_id||B.annotation_package_id!==N.package_id)throw Error('Paquetes no vinculados');const am=Object.fromEntries(A.reviews.map(x=>[key(x),x])),bm=Object.fromEntries(B.reviews.map(x=>[key(x),x]));diffs={{}};for(const o of N.observations){{const d=differences(am[o.observation_id],bm[o.observation_id]);if(d.length)diffs[o.observation_id]=d}}cards.innerHTML=Object.entries(diffs).map(([id,d])=>{{const o=N.observations.find(x=>x.observation_id===id),ref=f.observations.find(x=>x.observation_id===id);return`<section class="card" data-id="${{id}}"><h2>${{id}}</h2><img src="${{ref.reference_asset_path}}"><p>${{o.description_es}}</p><p>Discrepancias: ${{d.join(', ')}}</p><select class="decision"><option>include</option><option>exclude</option></select><label>Claims finales (desmarque para eliminar)</label>${{o.claims.map(c=>`<label><input type="checkbox" class="claim" value="${{c.claim_id}}" checked style="width:auto"> ${{c.text_es}}</label>`).join('')}}</section>`}}).join('')||'<p>Sin discrepancias.</p>';export.disabled=false}}catch(e){{alert(e.message)}}}};export.onclick=async()=>{{try{{if(!who.value.trim())throw Error('Falta adjudicador');const adjudication=Object.entries(diffs).map(([id,d])=>{{const o=N.observations.find(x=>x.observation_id===id),c=document.querySelector(`[data-id="${{id}}"]`),include=c.querySelector('.decision').value==='include';return{{observation_id:id,adjudicator_pseudonym:who.value.trim(),predictions_available:false,ground_truth_available:false,disagreement_ids:d,final_status:include?'include':'exclude',final_description_es:include?o.description_es:null,final_description_sha256:include?o.description_sha256:null,final_claim_ids:include?[...c.querySelectorAll('.claim:checked')].map(x=>x.value):[],exclusion_reasons:include?[]:['human_adjudication_exclusion'],adjudicated_at_utc:new Date().toISOString()}}}});const doc={{schema_version:'1.0',contract_version:'i20-review-package-v1',package_id:'',status:'frozen',annotation_package_id:N.package_id,reviewer_count:2,reviews:[...A.reviews,...B.reviews],adjudication}};doc.package_id='i20-review-package-sha256-'+await sha(stable(Object.fromEntries(Object.entries(doc).filter(([k])=>k!=='package_id'))));save('i20-review-adjudicated.json',doc)}}catch(e){{alert(e.message)}}}};document.documentElement.dataset.ready='true';</script></html>'''
def main():
 p=argparse.ArgumentParser();p.add_argument('--acquisition-root',type=Path,required=True);p.add_argument('--output-root',type=Path,required=True);p.add_argument('--scene-review',type=Path);a=p.parse_args();source=a.acquisition_root/'annotation-package';assignments=json.loads((source/'assignment-manifest.json').read_text());spatial=json.loads((a.acquisition_root/'spatial-audit.json').read_text());geographic=json.loads((a.acquisition_root/'geographic-package.json').read_text());annotation_dir=a.output_root/'annotation';refs=annotation_dir/'references';refs.mkdir(parents=True,exist_ok=True)
 opaque=[]
 for row in assignments['assignments']:
  source_path=source/row['reference_asset_path'];suffix=source_path.suffix.lower();name=f"{row['reference_asset_id']}{suffix}";destination=refs/name;shutil.copyfile(source_path,destination);opaque.append({**row,'reference_asset_path':f'references/{name}'})
 opaque_assignments={**assignments,'assignments':opaque};instructions_raw=(source/'INSTRUCTIONS_ES.md').read_bytes();fixture=build_annotation_fixture(opaque_assignments,annotation_dir,instructions_sha256=hashlib.sha256(instructions_raw).hexdigest())
 scene_dir=a.output_root/'scene-review';scene_dir.mkdir(parents=True,exist_ok=True);scene_refs=scene_dir/'references';scene_refs.mkdir(exist_ok=True)
 for path in refs.iterdir():shutil.copyfile(path,scene_refs/path.name)
 scene_fixture=build_scene_fixture(fixture,geographic,spatial);scene_fixture['records']=[{**r,'left_reference_path':'references/'+Path(r['left_reference_path']).name,'right_reference_path':'references/'+Path(r['right_reference_path']).name} for r in scene_fixture['records']];scene_fixture['fixture_sha256']=hashlib.sha256(canonical_bytes({k:v for k,v in scene_fixture.items() if k!='fixture_sha256'})).hexdigest();write(scene_dir/'fixture.json',scene_fixture);(scene_dir/'review-scenes.html').write_text(harden_html(scene_html(scene_fixture)),encoding='utf-8')
 if a.scene_review:
  scene_review=json.loads(a.scene_review.read_text());validate_scene_review(scene_review,scene_fixture)
  if scene_review.get('status')!='frozen':raise ValueError('scene review debe estar frozen para filtrar cohort')
